//! IDENTITY 列（TABLE-24・Issue #1695）の wire 越し検証（層 A。ポインタ:
//! `docs/spec/04-behavior/data-model.md` TABLE-24、`docs/spec/04-behavior/error-format.md` ERR-6）。
//!
//! 採番・拒否の意味論は engine の `sql::identity_column_tests` が確定オラクルとして検証済みのため、
//! 本ファイルは (1) `GENERATED ALWAYS` 列への明示値が SQLSTATE `428C9` で返ること
//! (2) `GENERATED BY DEFAULT` 列が明示値を受け付け、省略時は採番した値を返すこと、を
//! pg wire 越しに確認する。

#[path = "common/mod.rs"]
mod common;

#[path = "../../engine/src/test_util/temp_db.rs"]
mod temp_db;

use std::net::TcpStream;
use std::sync::Arc;

use engine::core::EngineCore;
use engine::kernel::CpuScalarProvider;
use engine::policy::PolicyContext;
use engine::sql::mode::SessionState;
use engine::storage::Storage;

use common::*;

fn setup() -> (Arc<EngineCore>, temp_db::CleanupGuard) {
    let path = temp_db::unique_db_path("wire-identity-column");
    let guard = temp_db::CleanupGuard(path.clone());
    let storage = Storage::open(&path).expect("open storage");
    let core = Arc::new(EngineCore::from_storage(
        storage,
        Box::new(CpuScalarProvider),
    ));
    // 管理用セッションで DDL を実行する（wire 経由の DDL 権限とは独立）。
    for sql in [
        "CREATE TABLE a (id BIGINT PRIMARY KEY, n INTEGER GENERATED ALWAYS AS IDENTITY, v TEXT)",
        "CREATE TABLE b (id BIGINT PRIMARY KEY, n BIGINT GENERATED BY DEFAULT AS IDENTITY, v TEXT)",
    ] {
        let mut session = SessionState::default();
        session.allow_ddl();
        let ctx = PolicyContext::new("tenant-a").expect("valid tenant id");
        core.execute_sql_in_session(&ctx, &mut session, sql)
            .unwrap_or_else(|e| panic!("{sql}: {e}"));
    }
    (core, guard)
}

fn connect(core: Arc<EngineCore>) -> TcpStream {
    let users_path = write_user_store_file(&[("alice", "tenant-a", "pw-alice")]);
    let addr = spawn_server_with_engine(&users_path, core);
    authenticate_to_ready_for_query(addr, "alice", "pw-alice")
}

/// ALWAYS 列への明示値・UPDATE は `428C9`。省略した INSERT は採番した値を返す。
#[test]
fn always_column_rejects_explicit_value_with_428c9() {
    let (core, _guard) = setup();
    let mut stream = connect(Arc::clone(&core));

    send_simple_query(
        &mut stream,
        "INSERT INTO a (id, n, v) VALUES (1, 5, 'x') USING OPERATION_ID 'wire-id-1'",
    );
    expect_error_response_with_sqlstate(&mut stream, "428C9");
    read_ready_for_query(&mut stream);

    send_simple_query(
        &mut stream,
        "INSERT INTO a (id, v) VALUES (1, 'x') RETURNING n USING OPERATION_ID 'wire-id-2'",
    );
    let _ = read_row_description(&mut stream);
    assert_eq!(read_data_row(&mut stream), vec![Some("1".to_string())]);
    assert_eq!(read_command_complete(&mut stream), "INSERT 0 1");
    read_ready_for_query(&mut stream);

    send_simple_query(
        &mut stream,
        "UPDATE a SET n = 9 WHERE id = 1 USING OPERATION_ID 'wire-id-3'",
    );
    expect_error_response_with_sqlstate(&mut stream, "428C9");
    read_ready_for_query(&mut stream);
}

/// BY DEFAULT 列は明示値を受け付け、省略時だけ採番する。
#[test]
fn by_default_column_accepts_explicit_value_and_numbers_omitted() {
    let (core, _guard) = setup();
    let mut stream = connect(Arc::clone(&core));

    send_simple_query(
        &mut stream,
        "INSERT INTO b (id, n, v) VALUES (1, 100, 'x') RETURNING n USING OPERATION_ID 'wire-id-4'",
    );
    let _ = read_row_description(&mut stream);
    assert_eq!(read_data_row(&mut stream), vec![Some("100".to_string())]);
    assert_eq!(read_command_complete(&mut stream), "INSERT 0 1");
    read_ready_for_query(&mut stream);

    send_simple_query(
        &mut stream,
        "INSERT INTO b (id, v) VALUES (2, 'y') RETURNING n USING OPERATION_ID 'wire-id-5'",
    );
    let _ = read_row_description(&mut stream);
    assert_eq!(read_data_row(&mut stream), vec![Some("1".to_string())]);
    assert_eq!(read_command_complete(&mut stream), "INSERT 0 1");
    read_ready_for_query(&mut stream);
}
